#!/bin/bash
set -euo pipefail

CONTAINERFILE_PATH="$AGENTEVAL_WORKSPACE_DIR/.agenteval-agenteval-claude.Containerfile"
cat > "$CONTAINERFILE_PATH" <<'CONTAINERFILE'
FROM docker.io/library/node:22-bookworm
RUN apt-get update && apt-get install -y --no-install-recommends bash git procps ca-certificates && rm -rf /var/lib/apt/lists/*
RUN npm install -g @anthropic-ai/claude-code@2.1.227
RUN mkdir -p /usr/local/lib/agenteval /workspace/.agenteval/claude
RUN node -e "require('node:fs').writeFileSync('/usr/local/lib/agenteval/agenteval-claude.mjs', Buffer.from('', 'base64'))" && chmod 0755 /usr/local/lib/agenteval/agenteval-claude.mjs && ln -s /usr/local/lib/agenteval/agenteval-claude.mjs /usr/local/bin/agenteval-claude
WORKDIR /workspace
CMD ["claude", "--help"]
CONTAINERFILE

node - "$CONTAINERFILE_PATH" <<'NODE'
const fs = require("node:fs");
const containerfile = fs.readFileSync(process.argv[2], "utf8");
const adapter = {
  agent_id: process.env.AGENTEVAL_AGENT_ID,
  name: "Anthropic Claude Code",
  description: "Pinned @anthropic-ai/claude-code npm agent with native stream-json retention and canonical event wrapper",
  format_version: 1,
  install_type: "npm",
  image: "localhost/agenteval-" + process.env.AGENTEVAL_AGENT_ID + ":latest",
  source_repo: null,
  source_ref: null,
  containerfile,
  default_provider: process.env.AGENTEVAL_PROVIDER,
  default_model: process.env.AGENTEVAL_MODEL,
  command: {
    argv: ["agenteval-claude", "{{prompt}}", "{{model}}", "{{provider}}", "{{run_id}}"],
    env: {},
    cwd: "/workspace",
    timeout_ms: 900000,
  },
  derive_connection_check: true,
  configure: null,
  provider_config: {"credentialEnv":{"anthropic":{"ANTHROPIC_API_KEY":"ANTHROPIC_API_KEY","ANTHROPIC_BASE_URL":"ANTHROPIC_BASE_URL"}}},
  parser_kind: "canonical-jsonl",
  parser_config: null,
  evidence: {
    paths: [".agenteval/claude"],
    required_paths: [".agenteval/claude"],
  },
  shared: true,
  enabled: true,
};
process.stdout.write(JSON.stringify(adapter));
NODE
